-- chair-step: inverse of read_lane_v2_b3_16_workbench_note_folders — un-enrolls workbench.note_folders from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'note_folders' and is_active);
select iam.apply_rls('workbench', 'note_folders', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'note_folders' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'note_folders' and is_active));
